<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { statusLabel } from '../status'
import { ElMessage,ElMessageBox } from 'element-plus'
import { api } from '../api'; import type { ResearchProduct,Store } from '../types'
const items=ref<ResearchProduct[]>([]), total=ref(0), loading=ref(false), search=ref(''), file=ref<File>(), categoryOpen=ref(false), importOpen=ref(false), current=ref<ResearchProduct>()
const category=reactive({description_category_id:0,type_id:0,display:''})
const stores=ref<Store[]>([]),importStore=ref(''),categoryOptions=ref<any[]>([]),selectedCategory=ref(''),categoryLoading=ref(false)
async function load(){loading.value=true;try{const r=await api.get<any>(`/research-products?search=${encodeURIComponent(search.value)}`);items.value=r.items;total.value=r.total}finally{loading.value=false}}
async function openImport(){stores.value=(await api.get<any>('/stores')).items.filter((x:Store)=>x.platform==='ozon'&&x.enabled);importStore.value=stores.value[0]?.id||'';importOpen.value=true;if(importStore.value)await loadCategories()}
async function loadCategories(){if(!importStore.value)return;categoryLoading.value=true;try{categoryOptions.value=(await api.get<any>(`/stores/${importStore.value}/category-options`)).items}finally{categoryLoading.value=false}}
async function upload(){const option=categoryOptions.value.find(x=>`${x.description_category_id}:${x.type_id}`===selectedCategory.value);if(!file.value)return ElMessage.warning('请先选择 Seerfar 表格');if(!option)return ElMessage.warning('请先选择本批商品使用的 OZON 实时末级类目');const f=new FormData();f.append('file',file.value);f.append('description_category_id',String(option.description_category_id));f.append('type_id',String(option.type_id));f.append('category_display',option.display);await api.upload('/research-products/imports/seerfar',f);ElMessage.success('已创建自动流程，导入完成后会生成各店铺草稿');file.value=undefined;importOpen.value=false}
function editCategory(row:ResearchProduct){current.value=row;category.description_category_id=row.description_category_id||0;category.type_id=row.type_id||0;category.display=row.category_display||'';categoryOpen.value=true}
async function saveCategory(){await api.put(`/research-products/${current.value!.id}/category`,category);categoryOpen.value=false;ElMessage.success('类目已确认');load()}
async function remove(row:ResearchProduct){await ElMessageBox.confirm(`确认从 ERP 删除 ${row.source_sku}？这会一并删除本地上架草稿，但不会删除 OZON、A4 产品库或原始图片。`,'删除本地商品',{type:'warning',confirmButtonText:'确认删除'});await api.delete(`/research-products/${row.id}`);ElMessage.success('本地商品记录已删除');load()}
onMounted(load)
</script>
<template><div class="page-stack"><section class="panel compact"><div class="toolbar"><el-input v-model="search" placeholder="SKU、标题或类目" clearable @keyup.enter="load"/><el-button @click="load">查询</el-button><span class="grow"/><el-button type="primary" @click="openImport">导入 Seerfar 并开始</el-button></div></section>
<section class="panel"><div class="panel-head"><div><h2>选品商品</h2><p>共 {{total}} 条，先确认 OZON 类目再进入找源</p></div></div><el-table v-loading="loading" :data="items"><el-table-column prop="source_sku" label="SKU" width="150"/><el-table-column label="商品" min-width="320"><template #default="s"><div class="product-cell"><el-image v-if="s.row.image_url" :src="s.row.image_url" fit="cover"/><div><b>{{s.row.title||'未命名商品'}}</b><small>{{s.row.category}}</small></div></div></template></el-table-column><el-table-column prop="selling_price_rub" label="售价 ₽" width="110"/><el-table-column prop="sales" label="销量" width="90"/><el-table-column prop="category_display" label="OZON 类目" min-width="170"/><el-table-column label="状态" width="150"><template #default="s">{{statusLabel(s.row.status)}}</template></el-table-column><el-table-column label="操作" width="170"><template #default="s"><el-button link type="primary" @click="editCategory(s.row)">确认类目</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></section>
<el-dialog v-model="categoryOpen" title="确认 OZON 类目" width="520"><el-form label-width="130"><el-form-item label="类目显示名称"><el-input v-model="category.display"/></el-form-item><el-form-item label="Description ID"><el-input-number v-model="category.description_category_id" :min="1"/></el-form-item><el-form-item label="Type ID"><el-input-number v-model="category.type_id" :min="1"/></el-form-item></el-form><template #footer><el-button @click="categoryOpen=false">取消</el-button><el-button type="primary" @click="saveCategory">保存</el-button></template></el-dialog>
<el-dialog v-model="importOpen" title="导入 Seerfar 并开始自动流程" width="620"><el-alert title="本次表格内全部商品使用同一个已确认的 OZON 类目，表格中的类目不会自动匹配。" type="warning" :closable="false"/><el-form label-width="120" style="margin-top:18px"><el-form-item label="读取类目的店铺"><el-select v-model="importStore" style="width:100%" @change="loadCategories"><el-option v-for="s in stores" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="OZON 末级类目"><el-select v-model="selectedCategory" filterable :loading="categoryLoading" style="width:100%"><el-option v-for="c in categoryOptions" :key="`${c.description_category_id}:${c.type_id}`" :label="c.display" :value="`${c.description_category_id}:${c.type_id}`"/></el-select></el-form-item><el-form-item label="Seerfar 表格"><input type="file" accept=".xlsx,.xlsm" @change="file=($event.target as HTMLInputElement).files?.[0]"/></el-form-item></el-form><template #footer><el-button @click="importOpen=false">取消</el-button><el-button type="primary" @click="upload">确认类目并导入</el-button></template></el-dialog></div></template>

